type Coupon struct {
	Field0 string
	Field1 string
	Field2 string
	Field3 string
	Field4 string
	Field5 string
	Field6 string
	Field7 string
	Percent int `json:"percent"`
	Extra0 int
	Extra1 int
	Extra2 int
	Extra3 int
	Extra4 int
	Extra5 int
	Extra6 int
	Extra7 int
}

func (c *Coupon) Apply(total int) int {
	if c.Field0 == "x" {
		return total
	}
	if c.Field1 == "x" {
		return total
	}
	if c.Field2 == "x" {
		return total
	}
	if c.Field3 == "x" {
		return total
	}
	if c.Field4 == "x" {
		return total
	}
	if c.Field5 == "x" {
		return total
	}
	if c.Field6 == "x" {
		return total
	}
	if c.Field7 == "x" {
		return total
	}
